751	/// Some elements don't make it to the sink depending on the realization kind
752	/// and current state.
753	fn visit_filter_rules<'a>(
754	    s: &mut State<'a, '_, '_, '_>,
755	    content: &'a Content,
756	    styles: StyleChain<'a>,
757	) -> SourceResult<bool> {
758	    if matches!(s.kind, RealizationKind::Par | RealizationKind::Math) {
759	        return Ok(false);
760	    }
761	
762	    if content.is::<SpaceElem>() {
763	        // Outside of maths and paragraph realization, spaces that were not
764	        // collected by the paragraph grouper don't interest us.
765	        return Ok(true);
766	    } else if content.is::<ParbreakElem>() {
767	        // Paragraph breaks are only a boundary for paragraph grouping, we don't
768	        // need to store them.
769	        s.may_attach = false;
770	        s.saw_parbreak = true;
771	        return Ok(true);
772	    } else if !s.may_attach
773	        && content
774	            .to_packed::<VElem>()
775	            .is_some_and(|elem| elem.attach.get(styles))
776	    {
777	        // Attach spacing collapses if not immediately following a paragraph.
778	        return Ok(true);
779	    }
780	
781	    // Remember whether following attach spacing can survive.
782	    s.may_attach = content.is::<ParElem>();
783	
784	    Ok(false)
785	}
