1102	/// Collects `ListItemLike` elements into a `ListLike` element.
1103	const fn list_like_grouping<T: ListLike>() -> GroupingRule {
1104	    GroupingRule {
1105	        priority: 2,
1106	        tags: false,
1107	        effect: |content| {
1108	            let elem = content.elem();
1109	            if elem == T::Item::ELEM {
1110	                GroupingEffect::Trigger
1111	            } else if elem == SpaceElem::ELEM || elem == ParbreakElem::ELEM {
1112	                GroupingEffect::Inner
1113	            } else {
1114	                GroupingEffect::Interrupt
1115	            }
1116	        },
1117	        interrupt: |elem| elem == T::ELEM || elem == AlignElem::ELEM,
1118	        finish: finish_list_like::<T>,
1119	    }
1120	}
